namespace Mfop.Infrastructure.Storage;

/// <summary>
/// S3-compatible object storage abstraction (ADR-0005). DEMO 1 uses <see cref="LocalFileSystemObjectStore"/>;
/// an S3 implementation with Object Lock replaces it in M8 through configuration. Buckets are fixed names
/// (see <see cref="Buckets"/>); keys are generated by the application, never taken from user input.
/// </summary>
public interface IObjectStore
{
    /// <summary>True for storage that cannot enforce write-once retention (the web shows "LOCAL STORAGE — NOT WORM").</summary>
    bool IsWorm { get; }

    Task PutAsync(string bucket, string key, Stream content, CancellationToken ct);

    /// <summary>Opens an object for reading, or null if it does not exist.</summary>
    Task<Stream?> OpenReadAsync(string bucket, string key, CancellationToken ct);

    Task<bool> ExistsAsync(string bucket, string key, CancellationToken ct);

    /// <summary>Only for the quarantine bucket (<see cref="Buckets.EvidenceIncoming"/>): verified originals are never deleted.</summary>
    Task DeleteIncomingAsync(string key, CancellationToken ct);

    /// <summary>Resumable upload into the quarantine bucket: bytes of the partial object received so far (0 if none).</summary>
    Task<long> IncomingPartLengthAsync(string key, CancellationToken ct);

    /// <summary>
    /// Appends a chunk to the partial object only if it holds exactly <paramref name="offset"/> bytes; never grows it past
    /// <paramref name="maxLength"/>. Returns whether the chunk was accepted and the partial length afterwards. If the
    /// connection drops mid-chunk, the bytes that did arrive stay, and the client resumes from the returned length.
    /// </summary>
    Task<(bool Accepted, long Length)> AppendIncomingPartAsync(string key, long offset, Stream chunk, long maxLength, CancellationToken ct);

    /// <summary>Turns the complete partial object into the object <paramref name="key"/> of the quarantine bucket.</summary>
    Task CompleteIncomingPartAsync(string key, CancellationToken ct);
}

public static class Buckets
{
    public const string EvidenceIncoming = "evidence-incoming";
    public const string Evidence = "evidence";
    public const string EvidenceDerived = "evidence-derived";
}

public sealed class ObjectStoreOptions
{
    /// <summary>"local" in DEMO 1 (the only implemented mode).</summary>
    public string Mode { get; set; } = "local";

    /// <summary>Root directory of the local store (a Docker volume in Compose).</summary>
    public string Root { get; set; } = "/var/lib/mfop/objects";
}

/// <summary>
/// Local filesystem store: one directory per bucket. Writes go to a temporary file first and are then moved into place,
/// so a reader never sees a half-written object. Not write-once: this is the documented DEMO 1 simplification.
/// </summary>
public sealed class LocalFileSystemObjectStore(string root) : IObjectStore
{
    private static readonly HashSet<string> KnownBuckets = [Buckets.EvidenceIncoming, Buckets.Evidence, Buckets.EvidenceDerived];

    public bool IsWorm => false;

    public async Task PutAsync(string bucket, string key, Stream content, CancellationToken ct)
    {
        var path = PathOf(bucket, key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var temp = path + "." + Guid.NewGuid().ToString("N") + ".tmp";
        await using (var file = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, useAsync: true))
        {
            await content.CopyToAsync(file, ct);
        }

        File.Move(temp, path, overwrite: true);
    }

    public Task<Stream?> OpenReadAsync(string bucket, string key, CancellationToken ct)
    {
        var path = PathOf(bucket, key);
        return Task.FromResult<Stream?>(File.Exists(path) ? new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true) : null);
    }

    public Task<bool> ExistsAsync(string bucket, string key, CancellationToken ct) => Task.FromResult(File.Exists(PathOf(bucket, key)));

    public Task DeleteIncomingAsync(string key, CancellationToken ct)
    {
        var path = PathOf(Buckets.EvidenceIncoming, key);
        if (File.Exists(path))
        {
            File.Delete(path);
        }

        return Task.CompletedTask;
    }

    public Task<long> IncomingPartLengthAsync(string key, CancellationToken ct)
    {
        var info = new FileInfo(PartOf(key));
        return Task.FromResult(info.Exists ? info.Length : 0L);
    }

    public async Task<(bool Accepted, long Length)> AppendIncomingPartAsync(string key, long offset, Stream chunk, long maxLength, CancellationToken ct)
    {
        var path = PartOf(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        FileStream file;
        try
        {
            file = new FileStream(path, FileMode.OpenOrCreate, FileAccess.Write, FileShare.None, 81920, useAsync: true);
        }
        catch (IOException)
        {
            return (false, await IncomingPartLengthAsync(key, ct)); // another chunk of the same upload is being written
        }

        await using (file)
        {
            if (file.Length != offset) return (false, file.Length);
            file.Seek(0, SeekOrigin.End);
            var buffer = new byte[81920];
            try
            {
                int n;
                while ((n = await chunk.ReadAsync(buffer, ct)) > 0)
                {
                    if (file.Length + n > maxLength)
                    {
                        file.SetLength(offset);
                        return (false, offset);
                    }

                    await file.WriteAsync(buffer.AsMemory(0, n), ct);
                }
            }
            catch (Exception e) when (e is IOException or OperationCanceledException) // incl. a client that disconnects mid-chunk
            {
                await file.FlushAsync(CancellationToken.None);
                return (false, file.Length);
            }

            return (true, file.Length);
        }
    }

    public Task CompleteIncomingPartAsync(string key, CancellationToken ct)
    {
        File.Move(PartOf(key), PathOf(Buckets.EvidenceIncoming, key), overwrite: true);
        return Task.CompletedTask;
    }

    private string PartOf(string key) => PathOf(Buckets.EvidenceIncoming, key) + ".part";

    private string PathOf(string bucket, string key)
    {
        if (!KnownBuckets.Contains(bucket))
        {
            throw new ArgumentException($"Unknown bucket '{bucket}'.", nameof(bucket));
        }

        if (key.Length == 0 || key.Contains("..", StringComparison.Ordinal) || key.Contains('\\') || Path.IsPathRooted(key))
        {
            throw new ArgumentException("Invalid object key.", nameof(key));
        }

        return Path.Combine(root, bucket, key);
    }
}
